        conversation_id: c6.id,
        connection_id: n4.id,
        uploaded_by: a6.user,
        kind: "image",
        name: "\u0424\u043E\u0442\u043E \u043C\u0435\u043D\u0435\u0434\u0436\u0435\u0440\u0430",
